head.script:
scwin.func = function() {
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
};
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    var ev = document.createEvent("MouseEvents");
    ev.initEvent("dblclick", true, true);
    el.dispatchEvent(ev);
}
scwin.checkId = function(id) {
    if (!WebSquare.wUnit.getDomById(id)) {
        return false;
    }
    return true;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 col1 의 inputType 부분을 확인한다.
    //1. In the Source tab or Property tab, check the inputType part of col1.
    //Verify step 1. inputType = "textarea
    //Test step 2. col2 의 inputType 부분을 확인한다.
    //2. Check the inputType part of col2.
    //Verify step 2. inputType = "calendar"
    //Test step 3. col3 의 inputType 부분을 확인한다.
    //3. Check the inputType part of col3.
    //Verify step 3. inputType = "button"
    //Test step 4. col3 의 disabled 부분을 확인한다.
    //4. Check the disabled part of col3.
    //Verify step 4. disabled = "true"
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('wq_uuid_3_cell_0_0')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_2').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_3_1').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkId('G_'+$p.id+'wq_uuid_3__col2_div_input')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.func();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 08-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
